test('resolves with every value', async () => {
  eq(await myPromiseAll([after(5, 1), after(10, 2)]), [1, 2]);
});

test('keeps input order, not completion order', async () => {
  eq(await myPromiseAll([after(30, 'a'), after(5, 'b')]), ['a', 'b']);
});

test('accepts plain values alongside promises', async () => {
  eq(await myPromiseAll([1, after(5, 2), Promise.resolve(3)]), [1, 2, 3]);
});

test('resolves with [] for an empty list', async () => {
  eq(await myPromiseAll([]), []);
});

test('rejects with the first rejection reason', async () => {
  await rejects(myPromiseAll([after(30, 'a'), failIn(5, 'boom')]), 'boom');
});

test('rejects without waiting for the pending ones', async () => {
  const p = myPromiseAll([never, failIn(5, 'early')]);
  await rejects(p, 'early');
});

test('returns a fresh array', async () => {
  const input = [1, 2];
  const out = await myPromiseAll(input);
  ok(out !== input, 'do not hand back the input array');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('describes a fulfilled input', async () => {
  eq(await myAllSettled([after(5, 'a')]), [
    { status: 'fulfilled', value: 'a' },
  ]);
});

test('describes a rejected input', async () => {
  const [record] = await myAllSettled([failIn(5, 'boom')]);
  eq(record.status, 'rejected');
  ok(record.reason instanceof Error);
  eq(record.reason.message, 'boom');
});

test('never rejects, even when everything fails', async () => {
  const out = await myAllSettled([failIn(5, 'a'), failIn(10, 'b')]);
  eq(out.map((r) => r.status), ['rejected', 'rejected']);
});

test('keeps input order', async () => {
  const out = await myAllSettled([after(30, 'slow'), failIn(5, 'fast')]);
  eq(out[0], { status: 'fulfilled', value: 'slow' });
  eq(out[1].status, 'rejected');
});

test('resolves with [] for an empty list', async () => {
  eq(await myAllSettled([]), []);
});

test('accepts plain values', async () => {
  eq(await myAllSettled([7]), [{ status: 'fulfilled', value: 7 }]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('resolves with the fastest value', async () => {
  eq(await myRace([after(60, 'slow'), after(5, 'fast')]), 'fast');
});

test('order in the array does not matter', async () => {
  eq(await myRace([after(5, 'fast'), after(60, 'slow')]), 'fast');
});

test('rejects when the first to settle is a rejection', async () => {
  await rejects(myRace([after(60, 'slow'), failIn(5, 'boom')]), 'boom');
});

test('a rejection after the race is over changes nothing', async () => {
  let rejectLate;
  const late = new Promise((_, reject) => {
    rejectLate = reject;
  });
  late.catch(() => {});
  const winner = myRace([after(5, 'fast'), late]);
  eq(await winner, 'fast');
  rejectLate(new Error('late'));
  eq(await winner, 'fast');
});

test('a plain value wins immediately', async () => {
  eq(await myRace([after(5, 'fast'), 'now']), 'now');
});

test('an empty list never settles', async () => {
  const winner = await Promise.race([myRace([]), after(20, 'still pending')]);
  eq(winner, 'still pending');
});

