// ──────────────────────────── tests ──────────────────────────────────────

test('sequential returns the values in order', async () => {
  resetTracker();
  eq(await loadSequential(['a', 'b']), ['a:1', 'b:2']);
});

test('sequential never has two calls in flight', async () => {
  resetTracker();
  await loadSequential(['a', 'b', 'c']);
  eq(tracker.maxInFlight, 1);
});

test('sequential finishes each call before starting the next', async () => {
  resetTracker();
  await loadSequential(['a', 'b']);
  eq(tracker.events, ['start:a', 'end:a', 'start:b', 'end:b']);
});

test('parallel returns the same values in input order', async () => {
  resetTracker();
  eq(await loadParallel(['a', 'b', 'c']), ['a:1', 'b:2', 'c:3']);
});

test('parallel starts everything before anything finishes', async () => {
  resetTracker();
  await loadParallel(['a', 'b', 'c', 'd']);
  const starts = ['start:a', 'start:b', 'start:c', 'start:d'];
  eq(tracker.events.slice(0, 4), starts);
  eq(tracker.maxInFlight, 4);
});

test('parallel beats sequential on the same work', async () => {
  resetTracker();
  const t0 = Date.now();
  await loadSequential(['a', 'b', 'c']);
  const slow = Date.now() - t0;
  const t1 = Date.now();
  await loadParallel(['a', 'b', 'c']);
  const fast = Date.now() - t1;
  ok(fast < slow, `parallel ${fast}ms should beat sequential ${slow}ms`);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('resolves with the value when the work is fast enough', async () => {
  eq(await withTimeout(after(5, 'v'), 60), 'v');
});

test('rejects when the work is too slow', async () => {
  await rejects(withTimeout(after(80, 'v'), 20), 'timed out');
});

test('the timeout error names the limit', async () => {
  await rejects(withTimeout(after(80, 'v'), 20), 'timed out after 20ms');
});

test('a rejection from the work wins if it lands first', async () => {
  await rejects(withTimeout(failIn(5, 'boom'), 60), 'boom');
});

test('does not wait for the full limit once the work is done', async () => {
  const t0 = Date.now();
  eq(await withTimeout(after(5, 'quick'), 3000), 'quick');
  ok(Date.now() - t0 < 500, 'the race must settle as soon as work does');
});

test('a late failure after the timeout changes nothing', async () => {
  await rejects(withTimeout(failIn(40, 'late'), 10), 'timed out');
  await sleep(50);
  ok(true, 'the late rejection must not blow up the process');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('returns the value without retrying when it works', async () => {
  const fn = makeFlaky(0);
  eq(await retry(fn, 3), 'ok');
  eq(fn.calls, 1);
});

test('retries until it succeeds', async () => {
  const fn = makeFlaky(2);
  eq(await retry(fn, 3), 'ok');
  eq(fn.calls, 3);
});

test('gives up after the allowed number of attempts', async () => {
  const fn = makeFlaky(99);
  await rejects(retry(fn, 3), 'attempt 3 failed');
  eq(fn.calls, 3);
});

test('rejects with the last error, not the first', async () => {
  const fn = makeFlaky(99);
  const err = await retry(fn, 2).then(
    () => null,
    (e) => e
  );
  eq(err.message, 'attempt 2 failed');
});

test('backs off between attempts', async () => {
  const fn = makeFlaky(99);
  const t0 = Date.now();
  await rejects(retry(fn, 3, 10), 'failed');
  ok(Date.now() - t0 >= 25, 'expected waits of about 10ms then 20ms');
});

test('retries a synchronous throw too', async () => {
  const fn = makeFlaky(1, { sync: true });
  eq(await retry(fn, 3), 'ok');
  eq(fn.calls, 2);
});

