test('maps every item, in input order', async () => {
  resetTracker();
  const out = await mapLimit(['a', 'b', 'c', 'd'], 2, fetchOne);
  eq(out, ['a0', 'b1', 'c2', 'd3']);
});

test('never runs more than `limit` at once', async () => {
  resetTracker();
  await mapLimit(['a', 'b', 'c', 'd', 'e', 'f'], 2, fetchOne);
  ok(tracker.maxInFlight <= 2, `saw ${tracker.maxInFlight} in flight`);
});

test('actually uses the whole budget', async () => {
  resetTracker();
  await mapLimit(['a', 'b', 'c', 'd', 'e', 'f'], 3, fetchOne);
  eq(tracker.maxInFlight, 3);
});

test('handles a limit larger than the list', async () => {
  resetTracker();
  eq(await mapLimit(['a', 'b'], 10, fetchOne), ['a0', 'b1']);
  eq(tracker.maxInFlight, 2);
});

test('resolves with [] for an empty list', async () => {
  resetTracker();
  eq(await mapLimit([], 2, fetchOne), []);
});

test('passes the index to the callback', async () => {
  resetTracker();
  eq(await mapLimit(['x'], 1, (item, i) => `${item}@${i}`), ['x@0']);
});

test('rejects if one of the calls fails', async () => {
  resetTracker();
  const fn = (id) =>
    id === 'c' ? Promise.reject(new Error('c broke')) : fetchOne(id, 0);
  await rejects(mapLimit(['a', 'b', 'c'], 2, fn), 'c broke');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('resolves each push with its own job result', async () => {
  resetTracker();
  const q = createQueue();
  eq(await q.push(slow('a', 5)), 'a');
});

test('never runs two jobs at once', async () => {
  resetTracker();
  const q = createQueue();
  await Promise.all([q.push(slow('a', 10)), q.push(slow('b', 5))]);
  eq(tracker.maxInFlight, 1);
});

test('keeps FIFO order even when the first job is slowest', async () => {
  resetTracker();
  const q = createQueue();
  await Promise.all([
    q.push(slow('a', 30)),
    q.push(slow('b', 5)),
    q.push(slow('c', 5)),
  ]);
  eq(tracker.order, ['a', 'b', 'c']);
});

test('a failing job rejects only its own promise', async () => {
  resetTracker();
  const q = createQueue();
  const bad = q.push(() => Promise.reject(new Error('bad job')));
  const good = q.push(slow('after', 5));
  await Promise.all([rejects(bad, 'bad job'), good]);
  eq(await good, 'after');
});

