    log('inner');
  };
  const outer = async () => {
    log('outer start');
    await inner();
    log('outer end');
  };
  log('script start');
  setTimeout(() => log('timeout'), 0);
  outer();
  Promise.resolve()
    .then(() => log('then A'))
    .then(() => log('then B'));
  log('script end');
  return done;
}

