      setTimeout(() => {
        fn.inFlight -= 1;
        if (fail) reject(new Error(`load failed for ${id}`));
        else resolve(`user:${id}`);
      }, ms)
    );
  });
  fn.inFlight = 0;
  fn.peak = 0;
  return fn;
}

