test('delivers a rejection to every caller and caches nothing', async () => {
  const load = makeLoader({ fail: true });
  const get = dedupe(load);
  const a = get('u1');
  const b = get('u1');
  await rejects(a, 'load failed for u1');
  await rejects(b, 'load failed for u1');
