// ─────────────────────────────────────────────────────────────────────────
//  37 · runWaterfall (steps that build a context)           ★★☆ core
//  concepts: sequential async · accumulating state · immutability
//  run: node 37-waterfall-context.js
// ─────────────────────────────────────────────────────────────────────────
//
//  A checkout is five steps and every step needs what the earlier ones
//  learned: the cart, then the customer, then the tax, then the charge.
//  Build `runWaterfall(steps, initial)`:
//
//      const steps = [
//        async () => ({ id: 1 }),
//        async (ctx) => ({ name: `u${ctx.id}` }),
//      ];
//      await runWaterfall(steps, {})   → { id: 1, name: 'u1' }
//
//  Rules:
//    · each step is `(ctx) => partialObject | undefined`
//    · steps run ONE AT A TIME, in order, each seeing the merged context
//    · a step's returned object is merged in; `undefined` changes nothing
//    · `initial` is never mutated
//    · if a step rejects, the whole thing rejects and later steps do not run
//
//  hint: a for...of loop with an await inside is the right shape here —
//  the one place where serialising on purpose is correct.

import { test, eq, ok, rejects, sleep, spy } from '../../_lib/check.js';

export const trace = [];
export const meter = { running: 0, peak: 0 };

export const reset = () => {
  trace.length = 0;
  meter.running = 0;
  meter.peak = 0;
};

// Builds a step that logs its start/end and returns `patch` (or patch(ctx)).
export function makeStep(name, patch, ms = 10) {
  return spy(async (ctx) => {
    meter.running += 1;
    meter.peak = Math.max(meter.peak, meter.running);
    trace.push(`${name}:start`);
    await sleep(ms);
    trace.push(`${name}:end`);
    meter.running -= 1;
    return typeof patch === 'function' ? patch(ctx) : patch;
  });
}

export function runWaterfall(steps, initial = {}) {
  throw new Error('TODO');
}

// ──────────────────────────── tests ──────────────────────────────────────

test('merges every step result into one context', async () => {
  reset();
  const steps = [makeStep('a', { id: 1 }), makeStep('b', { total: 20 })];
  eq(await runWaterfall(steps, {}), { id: 1, total: 20 });
});

test('a later step sees what the earlier ones produced', async () => {
  reset();
  const steps = [
    makeStep('a', { id: 1 }),
    makeStep('b', (ctx) => ({ name: `u${ctx.id}` })),
  ];
  eq(await runWaterfall(steps, { region: 'eu' }), {
    region: 'eu',
    id: 1,
    name: 'u1',
  });
});

test('runs the steps one at a time, in order', async () => {
  reset();
  const steps = [
    makeStep('a', { a: 1 }),
    makeStep('b', { b: 2 }),
    makeStep('c', { c: 3 }),
  ];
  await runWaterfall(steps, {});
  eq(trace, [
    'a:start',
    'a:end',
    'b:start',
    'b:end',
    'c:start',
    'c:end',
  ]);
  eq(meter.peak, 1, 'a waterfall never has two steps in flight');
});

test('does not mutate the object you passed in', async () => {
  reset();
  const initial = { region: 'eu' };
  const out = await runWaterfall([makeStep('a', { id: 1 })], initial);
  eq(initial, { region: 'eu' });
  ok(out !== initial, 'return a new object');
});

test('a step returning undefined leaves the context alone', async () => {
  reset();
  const steps = [makeStep('a', { id: 1 }), makeStep('log', undefined)];
  eq(await runWaterfall(steps, {}), { id: 1 });
