    meter.peak = Math.max(meter.peak, total);
    meter.perKeyPeak = Math.max(meter.perKeyPeak, running[key]);
    trace.push(`${name}:start`);
    await sleep(ms);
    trace.push(`${name}:end`);
    running[key] -= 1;
    if (fail) throw new Error(`${name} failed`);
    return name;
  };
