  const fn = spy(
    (amount) =>
      new Promise((resolve, reject) =>
        setTimeout(() => {
          fn.tries += 1;
          if (fn.tries <= failures) {
            reject(new Error(`gateway down (${fn.tries})`));
          } else {
            resolve(`charged:${amount}`);
          }
        }, 15)
      )
  );
  fn.tries = 0;
  return fn;
}

