  const init = makeInit();
  const gate = createGate(init);
  const values = await Promise.all(
    Array.from({ length: 10 }, () => gate.ensureReady())
  );
  eq(init.callCount, 1);
  eq(values[0], { pool: 1 });
  ok(values.every((v) => v === values[0]), 'everyone gets the same object');
